sfide.schema:
{
  "description": "Relazioni trimestrali in Word",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": true,
    "enableFigureAnalysis": true,
    "chartFormat": "chartjs"
  },
  "fieldSchema": {
    "fields": {
      "RicaviPerArea": {
        "type": "array",
        "description": "Una voce per ogni riga della tabella Area/Ricavi/Margine.",
        "items": {
          "type": "object",
          "properties": {
            "Area": {
              "type": "string"
            },
            "Ricavi": {
              "type": "number"
            },
            "MarginePercento": {
              "type": "number"
            }
          }
        }
      },
      "RicaviQ3Testo": {
        "type": "number",
        "method": "extract",
        "description": "Ricavi complessivi del terzo trimestre citati nel testo."
      },
      "UnitaDiMisura": {
        "type": "string",
        "method": "classify",
        "enum": [
          "euro",
          "migliaia di euro",
          "milioni di euro",
          "altro"
        ],
        "description": "Unità dei valori, dalla nota a piè di pagina."
      }
    }
  }
}

{
  "description": "Vendite mensili in Excel",
  "baseAnalyzerId": "prebuilt-document",
  "fieldSchema": {
    "fields": {
      "Vendite": {
        "type": "array",
        "description": "Una voce per prodotto del foglio Dati, escluse le righe marcate \"(vecchio)\".",
        "items": {
          "type": "object",
          "properties": {
            "Prodotto": {
              "type": "string"
            },
            "Totale": {
              "type": "number"
            }
          }
        }
      }
    }
  }
}

{
  "description": "Presentazioni con grafici",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "enableFigureAnalysis": true,
    "chartFormat": "chartjs"
  },
  "fieldSchema": {
    "fields": {
      "TabellaRicavi": {
        "type": "array",
        "description": "Righe della tabella di dettaglio.",
        "items": {
          "type": "object",
          "properties": {
            "Mese": {
              "type": "string"
            },
            "Ricavi": {
              "type": "number"
            }
          }
        }
      }
    }
  }
}

{
  "description": "Rendiconti acquisti in PDF",
  "baseAnalyzerId": "prebuilt-document",
  "fieldSchema": {
    "fields": {
      "Totale": {
        "type": "number",
        "method": "extract",
        "estimateSourceAndConfidence": true,
        "description": "Valore dopo \"Totale complessivo\", in fondo all'ultima pagina; non i subtotali di pagina."
      },
      "Righe": {
        "type": "array",
        "description": "Tutte le righe della tabella, anche quando continua sulla pagina successiva.",
        "items": {
          "type": "object",
          "properties": {
            "Codice": {
              "type": "string"
            },
            "Quantita": {
              "type": "number"
            },
            "Prezzo": {
              "type": "number"
            }
          }
        }
      }
    }
  }
}

{
  "description": "Tre documenti di acquisto collegati",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "enableSegment": true
  },
  "fieldSchema": {
    "fields": {
      "RiferimentoOrdine": {
        "type": "string",
        "method": "extract",
        "description": "Numero d'ordine nel formato OA- seguito da sei cifre."
      },
      "Righe": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
